#!/usr/bin/env bash
# tests/build-release.sh – assemble a LEANUX root filesystem and image.
#
# It uses build/libc-selection.tsv (generated by tools/select_libc.py) to take
# every package from the staging tree of the selected C library:
#
#   dietlibc  -> sysroot/install/<pkg>
#   glibc     -> sysroot-glibc/install/<pkg>
#
# The result is a mixed but runtime-consistent rootfs: dietlibc executables are
# static, glibc executables get the glibc runtime copied into the image.
#
# Usage:
#   ./tests/build-release.sh                       # image from existing stages
#   ./tests/build-release.sh --profile base        # build missing base packages
#   ./tests/build-release.sh --profile desktop     # X11/MATE desktop
#   ./tests/build-release.sh --profile world       # complete world order
#   ./tests/build-release.sh --profile base --image both
#   ./tests/build-release.sh --assemble-only       # never run builds
#   ./tests/build-release.sh --require-all         # fail on any missing package
#
# Options:
#   --profile NAME|FILE   built (default), all, world, base, desktop, path
#   --packages a,b,c      explicit package list (overrides profile)
#   --image img|iso|both  image format (default: img)
#   --out DIR             output directory (default: <repo>/out)
#   --size SIZE           ext4 image size, e.g. 2G (default: automatic)
#   --kernel FILE         kernel for the ISO (default: newest readable /boot)
#   --no-busybox          do not add the static busybox bootstrap shell
#   --assemble-only       only assemble existing stages, do not build
#   --force               rebuild selected packages even if staged
#   --timeout SECONDS     per-package build timeout (default: 3600)
#
# Results:
#   out/rootfs/                       assembled root filesystem
#   out/rootfs-manifest.tsv           package/libc/size list
#   out/runtime-deps.tsv              copied host runtime libraries
#   out/LEANUX-*.img                  ext4 image (mkfs.ext4 -d, no root needed)
#   out/LEANUX-*.iso                  bootable GRUB ISO (if requested)
#   out/RELEASE-BERICHT.md            German release report

set -uo pipefail

ROOT="$(cd "$(dirname "$(readlink -f "$0")")/.." && pwd)"
cd "$ROOT"

REPORT_DIR="${REPORT_DIR:-$ROOT/reports}"
OUT="${OUT:-$ROOT/out}"
PROFILE="built"
PACKAGES_ARG=""
IMAGE="img"
ASSEMBLE_ONLY=0
FORCE=0
WITH_BUSYBOX=1
REQUIRE_ALL=0
TIMEOUT="${RELEASE_BUILD_TIMEOUT:-3600}"
KERNEL="${KERNEL:-}"
IMAGE_SIZE="${IMAGE_SIZE:-}"
JOBS="${JOBS:-4}"
VERSION="$(grep -E '^version[[:space:]]*=' build/config.toml 2>/dev/null | head -1 | cut -d'"' -f2)"
VERSION="${VERSION:-0.1.0}"

DIET_STAGING="${DIET_STAGING_DIR:-$ROOT/sysroot}"
GLIBC_STAGING="${GLIBC_STAGING_DIR:-$ROOT/sysroot-glibc}"
DIET_BUILD="${DIET_BUILD_ROOT:-$ROOT/build-output}"
GLIBC_BUILD="${GLIBC_BUILD_ROOT:-$ROOT/build-output-glibc}"

SELECTION_TSV="$ROOT/build/libc-selection.tsv"

log()  { printf '[release] %s\n' "$*" >&2; }
warn() { printf '[release] WARNING: %s\n' "$*" >&2; }
die()  { printf '[release] ERROR: %s\n' "$*" >&2; exit 1; }

usage() {
    sed -n '2,38p' "$0"
}

while [ $# -gt 0 ]; do
    case "$1" in
        --profile)
            [ $# -ge 2 ] || die "--profile needs a value"
            PROFILE="$2"; shift 2 ;;
        --packages)
            [ $# -ge 2 ] || die "--packages needs a value"
            PACKAGES_ARG="$2"; shift 2 ;;
        --image)
            [ $# -ge 2 ] || die "--image needs a value"
            IMAGE="$2"; shift 2 ;;
        --out)
            [ $# -ge 2 ] || die "--out needs a value"
            OUT="$2"; shift 2 ;;
        --size)
            [ $# -ge 2 ] || die "--size needs a value"
            IMAGE_SIZE="$2"; shift 2 ;;
        --kernel)
            [ $# -ge 2 ] || die "--kernel needs a value"
            KERNEL="$2"; shift 2 ;;
        --timeout)
            [ $# -ge 2 ] || die "--timeout needs a value"
            TIMEOUT="$2"; shift 2 ;;
        --assemble-only|--skip-build) ASSEMBLE_ONLY=1; shift ;;
        --force) FORCE=1; shift ;;
        --no-busybox) WITH_BUSYBOX=0; shift ;;
        --require-all) REQUIRE_ALL=1; shift ;;
        --help|-h) usage; exit 0 ;;
        *) die "Unknown option: $1" ;;
    esac
done

case "$IMAGE" in
    img|iso|both) ;;
    *) die "Unknown image format: $IMAGE (expected img, iso or both)" ;;
esac
[ -n "$OUT" ] || die "refusing to use an empty output directory"
mkdir -p "$OUT" "$OUT/logs"
OUT="$(cd "$OUT" && pwd)"
if [ -n "$KERNEL" ]; then
    KERNEL="$(readlink -f "$KERNEL")"
fi
ROOTFS="$OUT/rootfs"

case "$PROFILE" in
    built) ASSEMBLE_ONLY=1 ;;
esac

# ---------------------------------------------------------------------------
# libc selection
# ---------------------------------------------------------------------------
log "erzeuge libc-Auswahl aus Matrix und Größenvergleich"
python3 tools/select_libc.py \
    --matrix "$REPORT_DIR/compile-matrix.tsv" \
    --comparison "$REPORT_DIR/libc-size-comparison.tsv" \
    --out-dir "$ROOT/build" --quiet \
    || die "libc selection failed (run compile-all.sh and compare-libc.sh first)"

declare -A SEL_LIBC=()
declare -A SEL_DIET=()
declare -A SEL_GLIBC=()
declare -A SEL_REASON=()
SELECTION_ORDER=()

# `read` with a tab IFS treats adjacent tabs as one delimiter and would drop
# empty columns such as an empty ratio.  Cut keeps every field, so the reason
# column always lands in field 8.
while IFS= read -r line; do
    case "$line" in
        ''|'#'*) continue ;;
    esac
    package="$(printf '%s' "$line" | cut -f1)"
    [ "$package" = "package" ] && continue
    libc="$(printf '%s' "$line" | cut -f2)"
    diet_bytes="$(printf '%s' "$line" | cut -f5)"
    glibc_bytes="$(printf '%s' "$line" | cut -f6)"
    reason="$(printf '%s' "$line" | cut -f8)"
    SEL_LIBC[$package]="$libc"
    SEL_DIET[$package]="$diet_bytes"
    SEL_GLIBC[$package]="$glibc_bytes"
    SEL_REASON[$package]="$reason"
    SELECTION_ORDER+=("$package")
done < "$SELECTION_TSV"

[ ${#SELECTION_ORDER[@]} -gt 0 ] || die "empty libc selection"

# ---------------------------------------------------------------------------
# package list
# ---------------------------------------------------------------------------
resolve_order_file() {
    case "$1" in
        all|built) return 1 ;;
        world|world-extras) echo "$ROOT/build/world.order" ;;
        base|desktop) echo "$ROOT/build/profiles/$1.order" ;;
        *) echo "$1" ;;
    esac
}

FAILED_BUILDS=()
MISSING_STAGES=()
EXCLUDED_PACKAGES=()

PACKAGES=()
if [ -n "$PACKAGES_ARG" ]; then
    IFS=',' read -r -a PACKAGES <<< "$PACKAGES_ARG"
elif order_file="$(resolve_order_file "$PROFILE")"; then
    [ -f "$order_file" ] || die "profile file not found: $order_file"
    while IFS= read -r line; do
        name="${line%%#*}"
        name="${name//[[:space:]]/}"
        [ -n "$name" ] && PACKAGES+=("$name")
    done < "$order_file"
else
    PACKAGES=("${SELECTION_ORDER[@]}")
fi

# The "built" profile only takes packages that already have a matching stage.
if [ "$PROFILE" = "built" ]; then
    filtered=()
    for pkg in "${PACKAGES[@]}"; do
        libc="${SEL_LIBC[$pkg]:-glibc}"
        if [ "$libc" = "dietlibc" ]; then
            stage="$DIET_STAGING/install/$pkg"
        else
            stage="$GLIBC_STAGING/install/$pkg"
        fi
        [ -f "$stage/.built" ] && filtered+=("$pkg") || EXCLUDED_PACKAGES+=("$pkg")
    done
    PACKAGES=("${filtered[@]}")
fi

[ ${#PACKAGES[@]} -gt 0 ] || die "no packages selected for profile $PROFILE"

log "Profil: $PROFILE, Pakete: ${#PACKAGES[@]}, Modus: $([ "$ASSEMBLE_ONLY" = 1 ] && echo assemble-only || echo build+assemble)"

stage_for() {
    local pkg="$1" libc="$2"
    if [ "$libc" = "dietlibc" ]; then
        printf '%s\n' "$DIET_STAGING/install/$pkg"
    else
        printf '%s\n' "$GLIBC_STAGING/install/$pkg"
    fi
}

stage_ok() {
    local stage="$1" libc="$2"
    [ -f "$stage/.built" ] || return 1
    local marker
    marker="$(cat "$stage/.libc" 2>/dev/null || true)"
    if [ "$libc" = "dietlibc" ]; then
        [ "$marker" = "dietlibc" ]
    else
        [ "$marker" = "glibc" ] || [ "$marker" = "glibc-fallback" ]
    fi
}

# ---------------------------------------------------------------------------
# build selected packages
# ---------------------------------------------------------------------------
build_package() {
    local pkg="$1" libc stage staging buildroot rc
    libc="${SEL_LIBC[$pkg]:-glibc}"
    stage="$(stage_for "$pkg" "$libc")"

    if [ "$FORCE" = 0 ] && stage_ok "$stage" "$libc"; then
        log "  vorhanden: $pkg ($libc)"
        return 0
    fi

    if [ "$libc" = "dietlibc" ]; then
        staging="$DIET_STAGING"; buildroot="$DIET_BUILD"
    else
        staging="$GLIBC_STAGING"; buildroot="$GLIBC_BUILD"
    fi

    log "  baue: $pkg ($libc)"
    rm -rf "$stage"
    env -u PKG_CONFIG_PATH -u PKG_CONFIG_SYSROOT_DIR \
        LIBC="$libc" STAGING_DIR="$staging" BUILD_ROOT="$buildroot" \
        SOURCES_DIR="$ROOT/sources" JOBS="$JOBS" \
        timeout --signal=TERM --kill-after=30 "$TIMEOUT" \
        ./spells/cast.sh --force "$pkg" \
        >> "$OUT/logs/build-$pkg.log" 2>&1
    rc=$?
    if [ "$rc" -ne 0 ] || ! stage_ok "$stage" "$libc"; then
        warn "$pkg ($libc) fehlgeschlagen (rc=$rc, Log: $OUT/logs/build-$pkg.log)"
        FAILED_BUILDS+=("$pkg")
        return 1
    fi
    return 0
}

if [ "$ASSEMBLE_ONLY" = 0 ]; then
    log "baue fehlende Pakete mit der gewählten libc"
    for pkg in "${PACKAGES[@]}"; do
        [ -f "$ROOT/spells/$pkg.spell" ] || { warn "kein Spell für $pkg"; MISSING_STAGES+=("$pkg"); continue; }
        build_package "$pkg" || true
    done
fi

# ---------------------------------------------------------------------------
# assemble rootfs
# ---------------------------------------------------------------------------
log "setze Rootfs zusammen: $ROOTFS"
rm -rf "$ROOTFS"
mkdir -p "$ROOTFS"

MANIFEST="$OUT/rootfs-manifest.tsv"
printf '# package\tlibc\tdiet_bytes\tglibc_bytes\tstage\tbytes\tfiles\n' > "$MANIFEST"

copy_stage() {
    local stage="$1" dest="$2"
    rsync -a \
        --exclude='.built' --exclude='.libc' --exclude='.gitkeep' \
        --exclude='*.a' --exclude='*.la' \
        --exclude='usr/include/' --exclude='usr/lib/pkgconfig/' \
        --exclude='usr/lib64/pkgconfig/' --exclude='usr/share/pkgconfig/' \
        --exclude='usr/share/man/' --exclude='usr/share/doc/' \
        --exclude='usr/share/info/' --exclude='usr/share/locale/' \
        --exclude='usr/share/aclocal/' --exclude='usr/share/cmake/' \
        --exclude='usr/share/gtk-doc/' --exclude='usr/share/gir-1.0/' \
        --exclude='usr/share/vala/' --exclude='usr/lib/cmake/' \
        --exclude='usr/lib/debug/' --exclude='__pycache__/' \
        "$stage"/ "$dest"/
}

INSTALLED=()
for pkg in "${PACKAGES[@]}"; do
    libc="${SEL_LIBC[$pkg]:-glibc}"
    stage="$(stage_for "$pkg" "$libc")"
    if ! stage_ok "$stage" "$libc"; then
        MISSING_STAGES+=("$pkg")
        warn "  übersprungen (keine passende Stufe): $pkg ($libc)"
        continue
    fi
    copy_stage "$stage" "$ROOTFS"
    measure="$(python3 tools/compare_report.py measure --stage "$stage" 2>/dev/null || printf '0\t0')"
    bytes="${measure%%$'\t'*}"
    files="${measure##*$'\t'}"
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' \
        "$pkg" "$libc" "${SEL_DIET[$pkg]:-0}" "${SEL_GLIBC[$pkg]:-0}" \
        "$stage" "$bytes" "$files" >> "$MANIFEST"
    INSTALLED+=("$pkg")
done

if [ ${#MISSING_STAGES[@]} -gt 0 ]; then
    warn "${#MISSING_STAGES[@]} Pakete ohne passende Stufe: ${MISSING_STAGES[*]}"
fi

# ---------------------------------------------------------------------------
# base configuration and bootstrap shell
# ---------------------------------------------------------------------------
mkdir -p "$ROOTFS"/{etc,dev,proc,sys,run,tmp,root,home,mnt,var/tmp,var/log,usr/bin,usr/sbin}
chmod 1777 "$ROOTFS/tmp" "$ROOTFS/var/tmp" 2>/dev/null || true
for link in bin:usr/bin sbin:usr/sbin lib:usr/lib lib64:usr/lib64; do
    name="${link%%:*}"
    target="${link##*:}"
    if [ ! -e "$ROOTFS/$name" ]; then
        [ -d "$ROOTFS/$target" ] && ln -s "$target" "$ROOTFS/$name"
    fi
done

cat > "$ROOTFS/etc/os-release" <<EOF
NAME="LEANUX"
ID=leanux
VERSION="${VERSION} (Erstausgabe)"
VERSION_ID="${VERSION}"
PRETTY_NAME="LEANUX ${VERSION}"
HOME_URL="https://leanux.invalid/"
EOF

cat > "$ROOTFS/etc/hostname" <<'EOF'
leanux
EOF
cat > "$ROOTFS/etc/hosts" <<'EOF'
127.0.0.1   localhost leanux
::1         localhost
EOF
cat > "$ROOTFS/etc/fstab" <<'EOF'
proc      /proc  proc      defaults  0 0
sysfs     /sys   sysfs     defaults  0 0
devtmpfs  /dev   devtmpfs  mode=0755 0 0
tmpfs     /tmp   tmpfs     mode=1777 0 0
EOF
cat > "$ROOTFS/etc/passwd" <<'EOF'
root:x:0:0:root:/root:/bin/sh
nobody:x:65534:65534:nobody:/nonexistent:/bin/false
EOF
cat > "$ROOTFS/etc/group" <<'EOF'
root:x:0:
tty:x:5:
disk:x:6:
wheel:x:10:root
nobody:x:65534:
EOF
cat > "$ROOTFS/etc/issue" <<EOF
LEANUX ${VERSION} – Erstausgabe
EOF

cat > "$ROOTFS/init" <<EOF
#!/bin/sh
# LEANUX first-stage init for a plain root filesystem.
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
mount -t proc proc /proc 2>/dev/null || true
mount -t sysfs sysfs /sys 2>/dev/null || true
mount -t devtmpfs devtmpfs /dev 2>/dev/null || mount -t tmpfs tmpfs /dev 2>/dev/null || true
mkdir -p /run /tmp /var/tmp /var/log
chmod 1777 /tmp /var/tmp 2>/dev/null || true
printf '\nLEANUX ${VERSION} - Erstausgabe\n\n'
# PID 1 must never exit: the kernel panics with "Attempted to kill init" when
# it does.  Respawn the shell instead of exec'ing it.
while :; do
    /bin/sh
    printf 'LEANUX: Shell beendet, starte neu...\n'
    sleep 1
done
EOF
chmod +x "$ROOTFS/init"

if [ "$WITH_BUSYBOX" = 1 ]; then
    if [ -x /usr/bin/busybox ]; then
        install -m755 /usr/bin/busybox "$ROOTFS/bin/busybox"
        while IFS= read -r applet; do
            [ -n "$applet" ] || continue
            case "$applet" in
                busybox|init|linuxrc) continue ;;
            esac
            if [ ! -e "$ROOTFS/bin/$applet" ] && [ ! -e "$ROOTFS/usr/bin/$applet" ] \
               && [ ! -e "$ROOTFS/sbin/$applet" ] && [ ! -e "$ROOTFS/usr/sbin/$applet" ]; then
                ln -s busybox "$ROOTFS/bin/$applet"
            fi
        done < <(/usr/bin/busybox --list)
        if [ -x "$ROOTFS/usr/bin/bash" ] && { [ ! -e "$ROOTFS/bin/sh" ] || [ -L "$ROOTFS/bin/sh" ]; }; then
            if [ -L "$ROOTFS/bin" ]; then
                ln -sfn bash "$ROOTFS/bin/sh"
            else
                ln -sfn ../usr/bin/bash "$ROOTFS/bin/sh"
            fi
        elif [ ! -e "$ROOTFS/bin/sh" ]; then
            ln -s busybox "$ROOTFS/bin/sh"
        fi
        log "Busybox-Bootstrap nach /bin/busybox installiert"
    else
        warn "busybox not found – image has no rescue shell fallback"
    fi
fi

# ---------------------------------------------------------------------------
# runtime libraries for dynamically linked glibc binaries
# ---------------------------------------------------------------------------
log "sammle glibc-Laufzeitbibliotheken"
python3 tools/collect_runtime_deps.py \
    --rootfs "$ROOTFS" --report "$OUT/runtime-deps.tsv" \
    || warn "runtime dependency scan failed"

# ---------------------------------------------------------------------------
# size and image
# ---------------------------------------------------------------------------
ROOTFS_BYTES=$(du -sb "$ROOTFS" | cut -f1)
ROOTFS_MB=$(du -sm "$ROOTFS" | cut -f1)
printf '%s\n' "$ROOTFS_BYTES" > "$OUT/rootfs-size-bytes.txt"
log "Rootfs: ${ROOTFS_MB} MiB (${ROOTFS_BYTES} Bytes)"

safe_name="${VERSION}-${PROFILE//\//_}"
IMG_FILE="$OUT/LEANUX-${safe_name}.img"
ISO_FILE="$OUT/LEANUX-${safe_name}.iso"
CREATED_IMAGES=()

create_img() {
    command -v mkfs.ext4 >/dev/null 2>&1 || die "mkfs.ext4 not found"
    local size_mb
    if [ -n "$IMAGE_SIZE" ]; then
        size_mb="$IMAGE_SIZE"
    else
        size_mb=$((ROOTFS_MB + ROOTFS_MB / 5 + 32))
    fi
    [ "$size_mb" -ge $((ROOTFS_MB + 8)) ] || die "image size too small for rootfs"
    log "erstelle ext4-Image: $IMG_FILE (${size_mb} MiB)"
    rm -f "$IMG_FILE"
    truncate -s "${size_mb}M" "$IMG_FILE"
    mkfs.ext4 -q -F -L LEANUX -E root_owner=0:0 -d "$ROOTFS" "$IMG_FILE" \
        || die "mkfs.ext4 failed"
    CREATED_IMAGES+=("$IMG_FILE")
}

find_kernel() {
    local candidate
    if [ -n "$KERNEL" ]; then
        [ -r "$KERNEL" ] || die "kernel not readable: $KERNEL"
        printf '%s\n' "$KERNEL"
        return 0
    fi
    for candidate in $(ls -1 /boot/vmlinuz-* 2>/dev/null | sort -rV); do
        if [ -r "$candidate" ]; then
            printf '%s\n' "$candidate"
            return 0
        fi
    done
    return 1
}

create_iso() {
    command -v mksquashfs >/dev/null 2>&1 || die "mksquashfs not found"
    command -v grub-mkrescue >/dev/null 2>&1 || die "grub-mkrescue not found"
    command -v cpio >/dev/null 2>&1 || die "cpio not found"
    local kernel isodir initrd
    kernel="$(find_kernel)" || die "no readable kernel found; pass --kernel FILE"
    isodir="$OUT/iso-root"
    initrd="$OUT/initramfs-root"
    rm -rf "$isodir" "$initrd"
    mkdir -p "$isodir/boot/grub" "$isodir/LEANUX" "$initrd/bin"

    log "erstelle Squashfs-Rootfs"
    mksquashfs "$ROOTFS" "$isodir/LEANUX/rootfs.squashfs" \
        -noappend -comp gzip -quiet >/dev/null || die "mksquashfs failed"

    log "erstelle Initramfs"
    install -m755 /usr/bin/busybox "$initrd/bin/busybox"

    # The kernel release must match the module tree, otherwise the initramfs
    # cannot load isofs/AHCI/USB drivers.  Prefer the version embedded in the
    # image and fall back to the file name.
    local kernel_version
    kernel_version="$(file -b "$kernel" | sed -n 's/.*version \([^ ]*\).*/\1/p')"
    if [ -z "$kernel_version" ]; then
        kernel_version="$(basename "$kernel" | sed 's/^vmlinuz-//')"
    fi
    [ -d "/lib/modules/${kernel_version}" ] || \
        die "no module tree for kernel ${kernel_version}; pass a matching --kernel"

    log "sammle Kernelmodule für ${kernel_version}"
    "$ROOT/tools/collect_kernel_modules.sh" \
        --kernel-version "$kernel_version" --dest "$initrd" \
        || die "kernel module collection failed"

    cat > "$initrd/init" <<'EOF'
#!/bin/busybox sh
export PATH=/bin:/sbin:/usr/bin:/usr/sbin
/bin/busybox mkdir -p /proc /sys /dev /run /mnt/cdrom /mnt/root
/bin/busybox mount -t proc proc /proc 2>/dev/null
/bin/busybox mount -t sysfs sysfs /sys 2>/dev/null
/bin/busybox mount -t devtmpfs devtmpfs /dev 2>/dev/null || \
    /bin/busybox mount -t tmpfs tmpfs /dev 2>/dev/null

if [ -f /modules.load ]; then
    while IFS= read -r module; do
        [ -n "$module" ] || continue
        /bin/busybox insmod "$module" 2>/dev/null
    done < /modules.load
fi

# Never let init exit: an exiting PID 1 makes the kernel panic.  Keep a rescue
# shell alive even when the console is misconfigured or the medium is missing.
rescue() {
    printf '\nLEANUX: %s\n' "$*" >&2
    printf 'LEANUX: Rettungsshell aktiv (Neustart: Strg+Alt+Entf).\n' >&2
    while :; do
        /bin/busybox sh
        /bin/busybox sleep 1
    done
}

# Wait up to 20 seconds for a CD/DVD, USB, VirtIO or NVMe device.  USB
# enumeration is asynchronous, so a single probe is not enough.
mounted=0
tries=0
while [ "$tries" -lt 20 ]; do
    for dev in /dev/sr* /dev/sd* /dev/vd* /dev/nvme*n*; do
        [ -b "$dev" ] || continue
        if /bin/busybox mount -t iso9660 -o ro "$dev" /mnt/cdrom 2>/dev/null; then
            if [ -f /mnt/cdrom/LEANUX/rootfs.squashfs ]; then
                mounted=1
                break
            fi
            /bin/busybox umount /mnt/cdrom 2>/dev/null
        fi
    done
    [ "$mounted" = 1 ] && break
    tries=$((tries + 1))
    /bin/busybox sleep 1
done
[ "$mounted" = 1 ] || rescue "LEANUX-Datentraeger nicht gefunden (rootfs.squashfs)."

# Prefer an explicit loop device; fall back to the mount helper.
loopdev="$(/bin/busybox losetup -f 2>/dev/null)"
if [ -n "$loopdev" ]; then
    /bin/busybox losetup "$loopdev" /mnt/cdrom/LEANUX/rootfs.squashfs 2>/dev/null \
        || loopdev=""
fi
if [ -n "$loopdev" ]; then
    /bin/busybox mount -t squashfs -o ro "$loopdev" /mnt/root 2>/dev/null \
        || rescue "squashfs konnte nicht eingebunden werden."
else
    /bin/busybox mount -t squashfs -o ro,loop \
        /mnt/cdrom/LEANUX/rootfs.squashfs /mnt/root 2>/dev/null \
        || rescue "squashfs konnte nicht eingebunden werden."
fi

[ -x /mnt/root/init ] || rescue "/mnt/root/init fehlt oder ist nicht ausführbar."

/bin/busybox mkdir -p /mnt/root/proc /mnt/root/sys /mnt/root/dev /mnt/root/run
/bin/busybox mount -o move /proc /mnt/root/proc 2>/dev/null || true
/bin/busybox mount -o move /sys /mnt/root/sys 2>/dev/null || true
/bin/busybox mount -o move /dev /mnt/root/dev 2>/dev/null || true
exec /bin/busybox switch_root /mnt/root /init
rescue "switch_root ist fehlgeschlagen."
EOF
    chmod +x "$initrd/init"
    (cd "$initrd" && find . -print0 | cpio --null -o --format=newc 2>/dev/null \
        | gzip -9 > "$isodir/boot/initramfs.img") || die "initramfs creation failed"

    cp "$kernel" "$isodir/boot/vmlinuz"
    # console=tty0 is the only console in the default entry.  A trailing
    # console=ttyS0 would make /dev/console unusable on machines without a
    # serial port (VirtualBox, most laptops); PID 1 then exits and the kernel
    # panics with "Attempted to kill init".  Serial users get their own entry.
    cat > "$isodir/boot/grub/grub.cfg" <<EOF
set default=0
set timeout=5

menuentry "LEANUX ${VERSION} (Erstausgabe)" {
    linux /boot/vmlinuz rdinit=/init console=tty0
    initrd /boot/initramfs.img
}

menuentry "LEANUX ${VERSION} (Erstausgabe, serielle Konsole)" {
    linux /boot/vmlinuz rdinit=/init console=tty0 console=ttyS0,115200n8
    initrd /boot/initramfs.img
}
EOF
    cat > "$isodir/LEANUX/README.txt" <<EOF
LEANUX ${VERSION} – Erstausgabe
Kernel: $(basename "$kernel")
Rootfs: squashfs (LEANUX/rootfs.squashfs)
Profil: ${PROFILE}
EOF

    log "erstelle GRUB-ISO: $ISO_FILE"
    rm -f "$ISO_FILE"
    grub-mkrescue -o "$ISO_FILE" "$isodir" >/dev/null 2>&1 \
        || die "grub-mkrescue failed"
    CREATED_IMAGES+=("$ISO_FILE")
}

case "$IMAGE" in
    img) create_img ;;
    iso) create_iso ;;
    both) create_img; create_iso ;;
esac

# ---------------------------------------------------------------------------
# German release report
# ---------------------------------------------------------------------------
REPORT="$OUT/RELEASE-BERICHT.md"
{
    echo "# LEANUX – Release-Bericht"
    echo
    echo "- Erzeugt: $(date -Iseconds)"
    echo "- Version: ${VERSION}"
    echo "- Profil: \`${PROFILE}\`"
    echo "- Pakete in der Rootfs: ${#INSTALLED[@]}"
    echo "- Rootfs-Größe: ${ROOTFS_MB} MiB"
    echo "- Ausgabe: \`${OUT}\`"
    echo
    echo "## Abbilder"
    echo
    for image in "${CREATED_IMAGES[@]}"; do
        echo "- \`${image}\` ($(du -h "$image" | cut -f1))"
    done
    echo
    echo "## libc-Verteilung"
    echo
    diet_count=0; glibc_count=0
    for pkg in "${INSTALLED[@]}"; do
        [ "${SEL_LIBC[$pkg]:-glibc}" = "dietlibc" ] && diet_count=$((diet_count + 1)) || glibc_count=$((glibc_count + 1))
    done
    echo "| libc | Pakete |"
    echo "|---|---:|"
    echo "| dietlibc | ${diet_count} |"
    echo "| glibc | ${glibc_count} |"
    echo
    echo "## Pakete"
    echo
    echo "| Paket | libc | Bytes | Begründung |"
    echo "|---|---|---:|---|"
    while IFS= read -r manifest_line; do
        case "$manifest_line" in ''|'#'*) continue ;; esac
        pkg="$(printf '%s' "$manifest_line" | cut -f1)"
        libc="$(printf '%s' "$manifest_line" | cut -f2)"
        bytes="$(printf '%s' "$manifest_line" | cut -f6)"
        echo "| \`${pkg}\` | ${libc} | ${bytes} | ${SEL_REASON[$pkg]:-} |"
    done < "$MANIFEST"
    echo
    echo "## Fehlende Pakete"
    echo
    if [ ${#MISSING_STAGES[@]} -gt 0 ] || [ ${#EXCLUDED_PACKAGES[@]} -gt 0 ]; then
        for pkg in "${MISSING_STAGES[@]}"; do echo "- \`${pkg}\` (keine passende Stufe)"; done
        for pkg in "${EXCLUDED_PACKAGES[@]}"; do echo "- \`${pkg}\` (noch nicht gebaut)"; done
    else
        echo "_Keine._"
    fi
    echo
    echo "## Fehlgeschlagene Builds"
    echo
    if [ ${#FAILED_BUILDS[@]} -gt 0 ]; then
        for pkg in "${FAILED_BUILDS[@]}"; do echo "- \`${pkg}\` (Log: \`${OUT}/logs/build-${pkg}.log\`)"; done
    else
        echo "_Keine._"
    fi
    echo
    echo "## Artefakte"
    echo
    echo "- Rootfs: \`${OUT}/rootfs/\`"
    echo "- Manifest: \`${OUT}/rootfs-manifest.tsv\`"
    echo "- Laufzeitbibliotheken: \`${OUT}/runtime-deps.tsv\`"
    echo "- libc-Auswahl: \`build/libc-selection.md\`"
} > "$REPORT"

log "fertig: ${#INSTALLED[@]} Pakete, ${ROOTFS_MB} MiB Rootfs"
for image in "${CREATED_IMAGES[@]}"; do log "Abbild: $image"; done
log "Bericht: $REPORT"

if [ "$REQUIRE_ALL" = 1 ] && { [ ${#MISSING_STAGES[@]} -gt 0 ] || [ ${#FAILED_BUILDS[@]} -gt 0 ] || [ ${#EXCLUDED_PACKAGES[@]} -gt 0 ]; }; then
    die "--require-all: es fehlen Pakete oder Builds sind fehlgeschlagen"
fi

exit 0
